diff --git a/scripts/eval/github.ts b/scripts/eval/github.ts
new file mode 100644
index 0000000..56b16f2
--- /dev/null
+++ b/scripts/eval/github.ts
@@ -0,0 +1,125 @@
+export type GithubRepo = { owner: string; repo: string };
+
+const PR_URL = /^https:\/\/github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)(?:\/.*)?$/u;
+
+export function parseGithubPrUrl(url: string): GithubRepo & { pr: number } {
+  const match = url.trim().match(PR_URL);
+  if (match === null || match[1] === undefined || match[2] === undefined || match[3] === undefined) {
+    throw new Error(`not a GitHub pull request URL: ${url}`);
+  }
+  return { owner: match[1], repo: match[2], pr: Number(match[3]) };
+}
+
+const COMMIT_URL = /^https:\/\/github\.com\/([^/]+)\/([^/]+)\/commit\/([0-9a-f]{7,40})(?:[/?#].*)?$/iu;
+const REPO_HTTPS = /^https:\/\/github\.com\/([^/]+)\/([^/]+)$/u;
+const REPO_SSH = /^git@github\.com:([^/]+)\/([^/]+)$/u;
+
+export function parseGithubCommitUrl(url: string): (GithubRepo & { sha: string }) | undefined {
+  const match = normalizeUrl(url).match(COMMIT_URL);
+  if (match?.[1] === undefined || match[2] === undefined || match[3] === undefined) {
+    return undefined;
+  }
+  return { owner: match[1], repo: match[2], sha: match[3].toLowerCase() };
+}
+
+export function parseGithubRepoRemote(url: string): GithubRepo | undefined {
+  const trimmed = url.trim().replace(/\.git$/u, "");
+  const https = trimmed.match(REPO_HTTPS);
+  if (https?.[1] !== undefined && https[2] !== undefined) {
+    return { owner: https[1], repo: https[2] };
+  }
+  const ssh = trimmed.match(REPO_SSH);
+  if (ssh?.[1] !== undefined && ssh[2] !== undefined) {
+    return { owner: ssh[1], repo: ssh[2] };
+  }
+  return undefined;
+}
+
+export function shaInRange(sha: string, rangeShas: readonly string[]): boolean {
+  const needle = sha.toLowerCase();
+  if (!/^[0-9a-f]{7,40}$/u.test(needle)) {
+    return false;
+  }
+  return rangeShas.some((full) => full.toLowerCase().startsWith(needle));
+}
+
+export function githubRepoUrl(owner: string, repo: string): string {
+  return `https://github.com/${owner}/${repo}.git`;
+}
+
+export function githubCacheName(owner: string, repo: string): string {
+  return `${owner}-${repo}.git`;
+}
+
+export function caseIdFor(repo: string, pr: number): string {
+  return `${repo}-${pr}`;
+}
+
+export function linkedIssueNumbers(text: string): number[] {
+  const found = new Set<number>();
+  const close = /\b(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\s+#(\d+)\b/giu;
+  for (const match of text.matchAll(close)) {
+    const raw = match[1];
+    if (raw !== undefined) {
+      found.add(Number(raw));
+    }
+  }
+  const full = /https:\/\/github\.com\/[^/]+\/[^/]+\/issues\/(\d+)/giu;
+  for (const match of text.matchAll(full)) {
+    const raw = match[1];
+    if (raw !== undefined) {
+      found.add(Number(raw));
+    }
+  }
+  return [...found].sort((a, b) => a - b);
+}
+
+export function normalizeUrl(url: string): string {
+  return url.trim().replace(/\/+$/u, "");
+}
+
+export function expandAllowedUrl(url: string): string[] {
+  const normalized = normalizeUrl(url);
+  const pull = normalized.match(/^(https:\/\/github\.com\/[^/]+\/[^/]+)\/pull\/(\d+)$/u);
+  if (pull?.[1] !== undefined && pull[2] !== undefined) {
+    return [normalized, `${pull[1]}/issues/${pull[2]}`];
+  }
+  return [normalized];
+}
+
+export function collectFrozenUrls(value: unknown): Set<string> {
+  const urls = new Set<string>();
+  walk(value, urls);
+  return urls;
+}
+
+function walk(value: unknown, urls: Set<string>): void {
+  if (Array.isArray(value)) {
+    for (const item of value) {
+      walk(item, urls);
+    }
+    return;
+  }
+  if (typeof value !== "object" || value === null) {
+    return;
+  }
+  for (const [key, item] of Object.entries(value)) {
+    if ((key === "html_url" || key === "url") && typeof item === "string" && /^https?:\/\//u.test(item)) {
+      for (const expanded of expandAllowedUrl(item)) {
+        urls.add(expanded);
+      }
+    } else {
+      walk(item, urls);
+    }
+  }
+}
+
+export function authedGitUrl(url: string, token: string | undefined): string {
+  if (token === undefined || token === "" || !url.startsWith("https://")) {
+    return url;
+  }
+  const parsed = new URL(url);
+  parsed.username = "x-access-token";
+  parsed.password = token;
+  return parsed.toString();
+}

diff --git a/scripts/eval/clone.ts b/scripts/eval/clone.ts
new file mode 100644
index 0000000..a3c61af
--- /dev/null
+++ b/scripts/eval/clone.ts
@@ -0,0 +1,88 @@
+import { mkdir } from "node:fs/promises";
+import { existsSync } from "node:fs";
+import { dirname, join } from "node:path";
+import { git, gitOk } from "../../src/git/exec.ts";
+import { parseGithubRepo } from "../pages-review.ts";
+import { authedGitUrl, githubCacheName } from "./github.ts";
+
+export function cachePath(cacheDir: string, repoUrl: string): string {
+  const parsed = parseGithubRepo(repoUrl);
+  if (parsed === undefined) {
+    throw new Error(`not a GitHub repo URL: ${repoUrl}`);
+  }
+  return join(cacheDir, githubCacheName(parsed.owner, parsed.repo));
+}
+
+export async function ensureBareClone(opts: {
+  cacheDir: string;
+  repoUrl: string;
+  localMirror?: string;
+}): Promise<string> {
+  const dest = cachePath(opts.cacheDir, opts.repoUrl);
+  const token = process.env.GH_TOKEN ?? process.env.GITHUB_TOKEN;
+  const remoteUrl = authedGitUrl(opts.repoUrl, token);
+  if (!existsSync(join(dest, "HEAD"))) {
+    await mkdir(opts.cacheDir, { recursive: true });
+    if (opts.localMirror !== undefined && existsSync(join(opts.localMirror, ".git"))) {
+      await git(opts.cacheDir, ["clone", "--bare", opts.localMirror, dest]);
+      const remotes = (await git(dest, ["remote"])).trim().split("\n");
+      if (!remotes.includes("github")) {
+        await git(dest, ["remote", "add", "github", remoteUrl]);
+      }
+    } else {
+      await git(dirname(dest), ["clone", "--bare", remoteUrl, dest]);
+    }
+  }
+  return dest;
+}
+
+export async function fetchCaseRefs(bare: string, pr: number, base: string, head: string): Promise<void> {
+  const remote = (await gitOk(bare, ["remote", "get-url", "github"])) ? "github" : "origin";
+  await git(bare, [
+    "fetch",
+    "--prune",
+    remote,
+    `+refs/pull/${pr}/head:refs/eval/pr-${pr}`,
+    "+refs/heads/main:refs/heads/main",
+    "+refs/heads/master:refs/heads/master",
+  ], { allowFail: true });
+  if (!(await gitOk(bare, ["cat-file", "-e", `${head}^{commit}`]))) {
+    await git(bare, ["fetch", remote, head]);
+  }
+  if (!(await gitOk(bare, ["cat-file", "-e", `${base}^{commit}`]))) {
+    await git(bare, ["fetch", remote, base]);
+  }
+  const missing = [];
+  if (!(await gitOk(bare, ["cat-file", "-e", `${head}^{commit}`]))) {
+    missing.push(`head ${head}`);
+  }
+  if (!(await gitOk(bare, ["cat-file", "-e", `${base}^{commit}`]))) {
+    missing.push(`base ${base}`);
+  }
+  if (missing.length > 0) {
+    throw new Error(`clone is missing ${missing.join(" and ")}`);
+  }
+}
+
+export async function addDetachedWorktree(bare: string, dest: string, head: string): Promise<void> {
+  await git(bare, ["worktree", "prune"], { allowFail: true });
+  await git(bare, ["worktree", "add", "--detach", dest, head]);
+}
+
+export async function removeWorktree(bare: string, dest: string): Promise<void> {
+  await git(bare, ["worktree", "remove", "--force", dest], { allowFail: true });
+  await git(bare, ["worktree", "prune"], { allowFail: true });
+}
+
+export async function thisRepoMirror(packageRoot: string, repoUrl: string): Promise<string | undefined> {
+  const wanted = parseGithubRepo(repoUrl);
+  if (wanted === undefined) {
+    return undefined;
+  }
+  const origin = (await git(packageRoot, ["config", "--get", "remote.origin.url"], { allowFail: true })).trim();
+  const parsed = parseGithubRepo(origin);
+  if (parsed === undefined || parsed.owner !== wanted.owner || parsed.repo !== wanted.repo) {
+    return undefined;
+  }
+  return packageRoot;
+}

diff --git a/scripts/eval/add-case.ts b/scripts/eval/add-case.ts
new file mode 100644
index 0000000..5afdd49
--- /dev/null
+++ b/scripts/eval/add-case.ts
@@ -0,0 +1,215 @@
+#!/usr/bin/env node
+
+import { execFile } from "node:child_process";
+import { realpathSync } from "node:fs";
+import { mkdir, writeFile } from "node:fs/promises";
+import { join, resolve } from "node:path";
+import { fileURLToPath } from "node:url";
+import { promisify } from "node:util";
+import { git } from "../../src/git/exec.ts";
+import { findPackageRoot } from "../../src/package-root.ts";
+import { ADD_CASE_USAGE, parseAddCaseArgv } from "./args.ts";
+import { caseIdFor, githubRepoUrl, linkedIssueNumbers, parseGithubPrUrl } from "./github.ts";
+import { ensureBareClone, thisRepoMirror } from "./clone.ts";
+
+const execFileAsync = promisify(execFile);
+
+export async function runAddCase(argv: string[], packageRoot = findPackageRoot()): Promise<number> {
+  const request = parseAddCaseArgv(argv);
+  if (request.kind === "help") {
+    console.log(ADD_CASE_USAGE);
+    return 0;
+  }
+  if (request.kind === "error") {
+    console.error(request.message);
+    console.error(`\n${ADD_CASE_USAGE}`);
+    return 1;
+  }
+  const parsed = parseGithubPrUrl(request.prUrl);
+  const id = request.id ?? caseIdFor(parsed.repo, parsed.pr);
+  const caseDir = join(packageRoot, "eval/cases", id);
+  const sourcesDir = join(caseDir, "sources");
+  await mkdir(sourcesDir, { recursive: true });
+
+  const pr = asRecord(await ghJson(["api", `repos/${parsed.owner}/${parsed.repo}/pulls/${parsed.pr}`]));
+  const reviewComments = await ghJsonList([
+    "api",
+    "--paginate",
+    "--slurp",
+    `repos/${parsed.owner}/${parsed.repo}/pulls/${parsed.pr}/comments`,
+  ]);
+  const conversationComments = await ghJsonList([
+    "api",
+    "--paginate",
+    "--slurp",
+    `repos/${parsed.owner}/${parsed.repo}/issues/${parsed.pr}/comments`,
+  ]);
+  await writeJson(join(sourcesDir, "pr.json"), trimPr(pr));
+  await writeJson(join(sourcesDir, "review-comments.json"), reviewComments.map(trimReviewComment));
+  await writeJson(join(sourcesDir, "comments.json"), conversationComments.map(trimIssueComment));
+
+  const body = typeof pr.body === "string" ? pr.body : "";
+  for (const issueNumber of linkedIssueNumbers(body)) {
+    try {
+      const issue = asRecord(
+        await ghJson(["api", `repos/${parsed.owner}/${parsed.repo}/issues/${issueNumber}`]),
+      );
+      await writeJson(join(sourcesDir, `issue-${issueNumber}.json`), trimIssue(issue));
+    } catch (error) {
+      console.error(`skip issue #${issueNumber}: ${error instanceof Error ? error.message : String(error)}`);
+    }
+  }
+
+  const head = nestedSha(pr, "head");
+  const mergeSha = typeof pr.merge_commit_sha === "string" ? pr.merge_commit_sha : undefined;
+  const repoUrl = githubRepoUrl(parsed.owner, parsed.repo);
+  const bare = await ensureBareClone({
+    cacheDir: join(packageRoot, "eval/.cache"),
+    repoUrl,
+    localMirror: await thisRepoMirror(packageRoot, repoUrl),
+  });
+  const remotes = (await git(bare, ["remote"])).trim().split("\n");
+  const remote = remotes.includes("github") ? "github" : "origin";
+  await git(bare, [
+    "fetch",
+    "--prune",
+    remote,
+    `+refs/pull/${parsed.pr}/head:refs/eval/pr-${parsed.pr}`,
+    "+refs/heads/main:refs/heads/main",
+    "+refs/heads/master:refs/heads/master",
+  ], { allowFail: true });
+  let base = nestedSha(pr, "base");
+  if (mergeSha !== undefined) {
+    await git(bare, ["fetch", remote, mergeSha], { allowFail: true });
+    base = (await git(bare, ["rev-parse", "--verify", `${mergeSha}^1`])).trim();
+  }
+
+  await writeJson(join(caseDir, "case.json"), {
+    id,
+    repo: repoUrl,
+    pr: parsed.pr,
+    base,
+    head,
+    tags: [],
+  });
+  console.log(caseDir);
+  return 0;
+}
+
+async function ghJson(args: string[]): Promise<unknown> {
+  const { stdout } = await execFileAsync("gh", args, { encoding: "utf8", maxBuffer: 32 * 1024 * 1024 });
+  return JSON.parse(stdout);
+}
+
+async function ghJsonList(args: string[]): Promise<unknown[]> {
+  const value = await ghJson(args);
+  if (Array.isArray(value)) {
+    if (value.length > 0 && Array.isArray(value[0])) {
+      return value.flat();
+    }
+    return value;
+  }
+  throw new Error(`expected JSON array from gh ${args.join(" ")}`);
+}
+
+async function writeJson(path: string, value: unknown): Promise<void> {
+  await writeFile(path, `${JSON.stringify(value, null, 2)}\n`);
+}
+
+function asRecord(value: unknown): Record<string, unknown> {
+  if (typeof value !== "object" || value === null || Array.isArray(value)) {
+    throw new Error("expected a JSON object from GitHub");
+  }
+  return value as Record<string, unknown>;
+}
+
+function nestedSha(pr: Record<string, unknown>, key: "head" | "base"): string {
+  const ref = pr[key];
+  if (typeof ref !== "object" || ref === null || !("sha" in ref) || typeof ref.sha !== "string" || ref.sha === "") {
+    throw new Error(`pull request ${key}.sha is missing`);
+  }
+  return ref.sha;
+}
+
+function trimUser(value: unknown): { login: string } | undefined {
+  if (typeof value !== "object" || value === null || !("login" in value) || typeof value.login !== "string") {
+    return undefined;
+  }
+  return { login: value.login };
+}
+
+function trimPr(pr: Record<string, unknown>): Record<string, unknown> {
+  return {
+    html_url: pr.html_url,
+    number: pr.number,
+    title: pr.title,
+    body: pr.body,
+    user: trimUser(pr.user),
+    merged_at: pr.merged_at,
+    merge_commit_sha: pr.merge_commit_sha,
+    base: trimRef(pr.base),
+    head: trimRef(pr.head),
+  };
+}
+
+function trimRef(value: unknown): { ref?: unknown; sha?: unknown } | undefined {
+  if (typeof value !== "object" || value === null) {
+    return undefined;
+  }
+  const ref = value as Record<string, unknown>;
+  return { ref: ref.ref, sha: ref.sha };
+}
+
+function trimIssue(issue: Record<string, unknown>): Record<string, unknown> {
+  return {
+    html_url: issue.html_url,
+    number: issue.number,
+    title: issue.title,
+    body: issue.body,
+    state: issue.state,
+    user: trimUser(issue.user),
+  };
+}
+
+function trimReviewComment(value: unknown): Record<string, unknown> {
+  const comment = asRecord(value);
+  return {
+    html_url: comment.html_url,
+    user: trimUser(comment.user),
+    body: comment.body,
+    path: comment.path,
+    side: comment.side,
+    line: comment.line,
+    original_line: comment.original_line,
+    original_commit_id: comment.original_commit_id,
+    commit_id: comment.commit_id,
+  };
+}
+
+function trimIssueComment(value: unknown): Record<string, unknown> {
+  const comment = asRecord(value);
+  return {
+    html_url: comment.html_url,
+    user: trimUser(comment.user),
+    body: comment.body,
+  };
+}
+
+const thisFile = fileURLToPath(import.meta.url);
+if (isAddCaseCliEntry(thisFile, process.argv[1])) {
+  process.exitCode = await runAddCase(process.argv.slice(2));
+}
+
+export function isAddCaseCliEntry(modulePath: string, argv1: string | undefined): boolean {
+  if (argv1 === undefined) {
+    return false;
+  }
+  try {
+    if (realpathSync(modulePath) === realpathSync(argv1)) {
+      return true;
+    }
+  } catch {
+    // tsx shims
+  }
+  return resolve(argv1).replaceAll("\\", "/").endsWith("scripts/eval/add-case.ts");
+}
